begin;
do $$declare o uuid;p uuid:=extensions.gen_random_uuid();r uuid:=extensions.gen_random_uuid();q jsonb;
begin
 select user_id into strict o from gac_private.owners limit 1;
 insert into public.gac_merch_products(id,name,price_cents,sizes,published)values(p,'Synthetic inventory test',100,array['S','M'],true);
 if(select count(*)from public.gac_merch_stock where product_id=p)<>2 or exists(select 1 from public.gac_merch_stock where product_id=p and quantity is not null)then raise exception 'Variants were not initialized as unset';end if;
 perform set_config('request.jwt.claim.sub',o::text,true);set local role authenticated;
 q:=public.gac_owner_change_merch_stock(p,'S','count',10,0,'Physical count',r);
 perform public.gac_owner_change_merch_stock(p,'S','count',10,0,'Physical count',r);
 if(q->>'quantity')<>'10'then raise exception 'Opening count failed';end if;
 begin perform public.gac_owner_change_merch_stock(p,'S','receive',5,0,'Stale tab',extensions.gen_random_uuid());raise exception 'Stale stock overwritten';exception when raise_exception then if position('Inventory changed'in sqlerrm)=0 then raise;end if;end;
 perform public.gac_owner_change_merch_stock(p,'S','receive',5,1,'Delivery',extensions.gen_random_uuid());
 perform public.gac_owner_change_merch_stock(p,'S','sale',3,2,'In-person sale',extensions.gen_random_uuid());
 begin perform public.gac_owner_change_merch_stock(p,'S','sale',13,3,'Too many',extensions.gen_random_uuid());raise exception 'Negative stock allowed';exception when raise_exception then if position('Not enough stock'in sqlerrm)=0 then raise;end if;end;
 perform public.gac_owner_change_merch_stock(p,'M','count',25,0,'Medium opening count',extensions.gen_random_uuid());reset role;
 if(select quantity from public.gac_merch_stock where product_id=p and size='S')<>12 or(select quantity from public.gac_merch_stock where product_id=p and size='M')<>25 then raise exception 'Stock or size isolation incorrect';end if;
 if(select count(*)from gac_private.merch_stock_events where product_id=p)<>4 then raise exception 'Stock replay duplicated ledger';end if;
 update public.gac_merch_products set sizes=array['M','L']where id=p;
 if(select quantity from public.gac_merch_stock where product_id=p and size='S')<>12 or not exists(select 1 from public.gac_merch_stock where product_id=p and size='L'and quantity is null)then raise exception 'Size edit lost old stock';end if;
 perform set_config('request.jwt.claim.sub','',true);set local role anon;
 if(select count(*)from public.gac_merch_stock where product_id=p)<>2 then raise exception 'Retired size exposed';end if;reset role;
 update public.gac_merch_products set published=false where id=p;
 set local role anon;if exists(select 1 from public.gac_merch_stock where product_id=p)then raise exception 'Hidden product stock exposed';end if;reset role;
 perform set_config('request.jwt.claim.sub',extensions.gen_random_uuid()::text,true);set local role authenticated;
 begin perform public.gac_owner_change_merch_stock(p,'M','count',1,1,'Unauthorized',extensions.gen_random_uuid());raise exception 'Nonowner changed stock';exception when insufficient_privilege then null;end;
 reset role;
 if has_table_privilege('authenticated','public.gac_merch_stock','update')or has_table_privilege('anon','public.gac_merch_stock','insert')or has_table_privilege('authenticated','gac_private.merch_stock_events','select')then raise exception 'Inventory write or ledger privileges exposed';end if;
end $$;
rollback;
